<script lang="ts">import { onMount } from 'svelte';import { SystemService, EventService, SessionService } from '../../lib/api';import { processes } from '../../lib/state/processes.svelte';import { router } from '../../lib/router.svelte';let stats = $state({ projects: 0, processes: 0, sessions: 0, processesRunning: 0, processesFailed: 0, logDiskBytes: 0, uptimeSeconds: 0 });let recent = $state<Record<string, unknown>[]>([]);let sessions = $state<Record<string, unknown>[]>([]);onMount(() => { void SystemService.stats().then((s) => (stats = { ...stats, ...(s as unknown as typeof stats) })).catch(() => {}); void EventService.list('', 20).then((r) => (recent = (r.events as unknown as Record<string, unknown>[]).slice(0, 20))).catch(() => {}); void SessionService.list().then((s) => (sessions = s as unknown as Record<string, unknown>[])).catch(() => {}); processes.connect('', true); return () => processes.disconnect(); });</script><div class="ov"><h2>Overview</h2><div class="cards"><button onclick={() => void router.navigate('/processes')}>Running<br /><b>{processes.counts.running}</b></button><button onclick={() => void router.navigate('/processes')}>Failed<br /><b>{processes.counts.failed}</b></button><div>Projects<br /><b>{stats.projects}</b></div><div>Sessions<br /><b>{sessions.length}</b></div><div>Log disk<br /><b>{Math.round(stats.logDiskBytes / 1024)} KB</b></div><div>Uptime<br /><b>{stats.uptimeSeconds}s</b></div></div>{#if processes.counts.failed > 0}<div class="attention"><h3>Needs attention</h3>{#each processes.list.filter((p) => p.status === 'failed' || p.status === 'crashed') as p}<div>{p.command} <button onclick={() => void router.navigate(`/processes/${p.id}`)}>View logs</button></div>{/each}</div>{/if}<h3>Recent events</h3><ul>{#each recent as e}<li>{String(e['type'])} · {String(e['processId'] ?? '')}</li>{/each}</ul></div><style>.ov{padding:var(--space-5)}.cards{display:grid;grid-template-columns:repeat(auto-fill,minmax(140px,1fr));gap:var(--space-4);margin:var(--space-4) 0}.cards>*{background:var(--bg-1);border:1px solid var(--border);border-radius:var(--radius-lg);padding:var(--space-4);text-align:left;color:var(--text-0)}.attention{background:var(--bg-1);border:1px solid var(--err);border-radius:var(--radius);padding:var(--space-4);margin:var(--space-4) 0}</style>
